/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Outer controller class for the order shipment bundling reporting job.
/// </summary> 
class METOrderShipmentBundlingReportingJobOuterController extends SrsReportRunController 
{
    #AssetTransfer

    METOrderTransactionType transactionType;
    METThreadCount threadCount;
    str innerControllerCaption;

}

Method.Source:
/// <summary>
/// Run method
/// </summary>
public void run()
{
   Args argsval = this.parmArgs();

    if (!this.isDialogCancelled())
    {
        this.initFromArgs(argsval);
        METOrderShipmentBundlingReportingJobInnerController innerController;

        innerController = METOrderShipmentBundlingReportingJobInnerController::construct();
        innerController.parmArgs(argsval); 

        this.validateInnerController();
        this.initInnerController(innerController);

        innerController.parmShowDialog(false);
        innerController.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);

        innerController.startOperation();
    }
   // return; 
}

/// <summary>
/// Constructs <c>METOrderShipmentBundlingReportingJobOuterController</c>.
/// </summary>
/// <returns>
/// <c>METOrderShipmentBundlingReportingJobOuterController</c>.
/// </returns>
public static METOrderShipmentBundlingReportingJobOuterController construct()
{
    return new METOrderShipmentBundlingReportingJobOuterController();
}

/// <summary>
/// Starts the process.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METOrderShipmentBundlingReportingJobOuterController controller;

    controller = METOrderShipmentBundlingReportingJobOuterController::construct();

    controller.parmArgs(_args);
    controller.initFromArgs(_args);
    controller.initReportContract();
    controller.startOperation();

}

/// <summary>
/// Validates inner controller.
/// </summary>
private void validateInnerController()
{

    if (threadCount <= 0)
    {
        str errorMessage;

        if (transactionType == METOrderTransactionType::SalesOrder)
        {
            errorMessage = "@MET:SalesOrderShipmentBundlingReportingThreadCountNotDefined";
        }
        else
        {
            errorMessage = "@MET:TransferOrderShipmentBundlingReportingThreadCountNotDefined";
        }

        throw error(errorMessage);
    }
}

/// <summary>
/// Initializes report contract.
/// </summary>
private void initReportContract()
{
    METOrderShipmentBundlingReportContract contract;

    contract = this.parmReportContract().parmRdpContract();

    contract.parmTransactionType(transactionType);
    contract.parmIsMultiThreadedJob(true);
}

/// <summary>
/// Modifies contract before prompting.
/// </summary>
protected void prePromptModifyContract()
{
    super();

    Query query =  this.getFirstQuery();

    this.initQuery(query);
}

/// <summary>
/// Initializes query.
/// </summary>
/// <param name = "_query">Query.</param>
private void initQuery(Query _query)
{
    QueryBuilddataSource qbds;

    qbds = _query.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader));

    if (qbds)
    {
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, LoadId));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, Route));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, RouteStopNum));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, SentToLaserNet)).value(enum2Str(NoYes::No));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, LoadStatus)).value(enum2Str(MetShipmentStatus::Shipped));

        var qbrTransactionType = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, TransactionType));
        qbrTransactionType.value(enum2Str(transactionType));
        qbrTransactionType.status(RangeStatus::Locked);

        var qbrWarehouse = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, Warehouse));

        if (transactionType == METOrderTransactionType::TransferOrder)
        {
            qbrWarehouse.label("@SYS25253");
            SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, ToWarehouse));
        }

    }

}

/// <summary>
/// Initializes <c>METOrderShipmentBundlingReportingJobInnerController</c>.
/// </summary>
/// <param name = "_innerController">
/// <c>METOrderShipmentBundlingReportingJobInnerController</c>.
/// </param>
private void initInnerController(METOrderShipmentBundlingReportingJobInnerController _innerController)
{
    METOrderShipmentBundlingReportingJobContract innerContract;
    SRSPrintDestinationSettings reportPrintDestSettings;

    reportPrintDestSettings = this.parmReportContract().parmPrintSettings();
    innerContract = _innerController.getDataContractObject() as METOrderShipmentBundlingReportingJobContract;

    innerContract.parmTranscationType(transactionType);
    innerContract.parmThreadCount(threadCount);
    innerContract.setQuery(this.getFirstQuery());
    innerContract.setPrintDestinationSettings(reportPrintDestSettings);
    _innerController.parmDialogCaption(innerControllerCaption);
}

/// <summary>
/// Initializes contoller and contract.
/// </summary>
/// <param name = "_args">Args.</param>
public void initFromArgs(Args _args)
{
    str report;

    transactionType = _args.parmEnum();

    switch (transactionType)
    {
        case METOrderTransactionType::SalesOrder:
            report = ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport);
            threadCount = WHSParameters::find().METSalesOrderBundlingReportingJobThreadCount;
            innerControllerCaption = "@MET:SalesOrderShipmentBundlingReportingJob";
            break;

        case METOrderTransactionType::TransferOrder:
            report = ssrsReportStr(METTransferOrderShipmentBundlingReport, Report);
            threadCount = WHSParameters::find().METTransferOrderBundlingReportingJobThreadCount;
            innerControllerCaption = "@MET:TransferOrderShipmentBundlingReportingJob";
            break;

        default:
            throw error(Error::wrongUseOfFunction(funcName()));
    }

   this.parmReportName(report);
}

/// <summary>
/// method returns boolean value based on the dialog form cancelled or not
/// </summary>
/// <returns>boolean</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}
